   cur_item    = 0;
   mode        = BUY_MODE;

   if ( mode == BUY_MODE )
   {
      SWD_SetFieldItem ( window, STOR_BUY, buybut [0] );
      SWD_SetFieldItem ( window, STOR_SELL, sellbut [1] );
